def kind(a, b, c):
    m = max(a, b, c)
    return '직각삼각형' if m == 90 else ('둔각삼각형' if m > 90 else '예각삼각형')
def sk(x, y, z):
    s = {x, y, z}
    return '정삼각형' if len(s) == 1 else ('이등변삼각형' if len(s) == 2 else '세 변의 길이가 모두 다른 삼각형')

