    def TS(bs, l, r, u='cm'): return f'[[fig:ts:{bs}:{l}:{r}:{u}]]'
    def TG(a, c, d): return f'[[fig:tg:{a}:{c}:{d}]]'
    def TK(a, c): return f'[[fig:tk:{a}:{c}]]'
    KINDS3 = ['예각삼각형', '직각삼각형', '둔각삼각형']

